def pre(xs):
    if len(xs) < 1:
        return False
    return True

def max_run_sum(xs):
    n = len(xs)
    best = xs[0]
    for i in range(n):
        s = 0
        for j in range(i, n):
            s = s + xs[j]
            if s > best:
                best = s
    return best

def post(xs, result):
    if len(xs) < 1:
        return False
    return result == max_run_sum(xs)
